SELECT table_name,
       column_name,
       data_type
FROM information_schema.columns
WHERE table_schema = 'public'
  AND column_name IN ('storage_provider', 'storage_key')
ORDER BY table_name, column_name;

NOTIFY pgrst, 'reload schema';


